type Seed = {
  id: MechanismId;
  title: string;
  shortTitle: string;
  tagline: string;
  explanation: string;
  tempo: Tempo;
  marker: readonly [number, number, number];
  states: [string, string, string];
  misconception: string;
  benefit: string;
  cost: string;
  source?: EvidenceReference;
  pressure?: boolean;
};

function mechanism(seed: Seed): MechanismSpec {
  const districtId = seed.id.split(".")[0] as DistrictId;
  const districtPosition = POSITIONS[districtId];
  const source = seed.source ?? sources[districtId];
  const claim: Claim = {
    id: `${seed.id}-claim`,
    text: seed.explanation,
    kind: "derived",
    version: CLICKHOUSE_CLAIM_VERSION,
    source,
  };
  const tradeoffs: Tradeoff[] = [{ benefit: seed.benefit, cost: seed.cost }];
  return {
    id: seed.id,
    districtId,
    title: seed.title,
    shortTitle: seed.shortTitle,
    tagline: seed.tagline,
    explanation: seed.explanation,
    tempo: seed.tempo,
    cameraPose: {
      position: [districtPosition[0] + 7.8, 8.8, 11.8],
      target: [districtPosition[0] + seed.marker[0] * 0.18, 2.1, seed.marker[2] * 0.16],
      zoom: 32,
    },
    markerPosition: seed.marker,
    states: seed.states,
    transitions: [
      { from: seed.states[0], to: seed.states[1], label: seed.tagline },
      { from: seed.states[1], to: seed.states[2], label: `Finish as ${seed.states[2].toLowerCase()}` },
    ],
    healthyScenarioId: `${seed.id}.healthy`,
    pressureScenarioId: seed.pressure ? `${seed.id}.pressure` : undefined,
    claimIds: [source.id],
    claims: [claim],
    tradeoffs,
    relatedMechanismIds: [],
    misconception: seed.misconception,
    reducedMotionSummary: `${seed.states[0]} changes directly to ${seed.states[2]}; labels preserve the intermediate ${seed.states[1].toLowerCase()} state.`,
  };
}

