export const MECHANISMS: MechanismSpec[] = seeds.map(mechanism);

const district = (id: DistrictId, index: number, title: string, shortTitle: string, description: string, accent: string): DistrictSpec => ({
  id,
  index,
  title,
  shortTitle,
  description,
  position: POSITIONS[id],
  accent,
  mechanismIds: MECHANISMS.filter((entry) => entry.districtId === id).map((entry) => entry.id),
});

export const DISTRICTS: DistrictSpec[] = [
  district("ingestion", 1, "Arrival manifold", "Ingest", "Rows become coordinated batches before they create parts.", "#FFCC01"),
  district("mergetree", 2, "MergeTree foundry", "Parts", "Immutable columnar parts are assembled, selected, and merged.", "#E6A52E"),
  district("read", 3, "Query scanner", "Read", "Indexes, granules, columns, and pipelines reveal avoided work.", "#78D7D2"),
  district("precompute", 4, "Derived-data switchyard", "Precompute", "Views and projections exchange write work for predictable reads.", "#A8C96B"),
  district("architecture", 5, "Cluster switchboard", "Scale", "Shards, replicas, and Keeper expose distributed failure domains.", "#8F82CE"),
  district("retention", 6, "Time & rewrite vault", "Retain", "TTL, mutations, backups, and restores govern the long tail.", "#D64C3F"),
  district("memory", 7, "Cache & memory tower", "Memory", "Page cache, ClickHouse caches, limits, and spill reveal where bytes wait.", "#4C8C86"),
  district("execution", 8, "Query execution lab", "Execute", "Analyzer, plans, joins, processors, and scheduling turn SQL into work.", "#2C6E9D"),
  district("durability", 9, "Commit & quorum dock", "Durability", "Part commit, acknowledgement, replicated logs, and quorum define when an insert is done.", "#D59612"),
  district("storage", 10, "Storage tier exchange", "Storage", "Disks, volumes, policies, object storage, caches, and codecs place every byte.", "#6A7B8B"),
  district("observability", 11, "System-table observatory", "Observe", "ClickHouse system tables expose queries, parts, merges, replicas, and internal counters.", "#7C5FB4"),
];

for (const districtSpec of DISTRICTS) {
  const ids = districtSpec.mechanismIds;
  ids.forEach((id, index) => {
    const spec = MECHANISMS.find((entry) => entry.id === id);
    if (!spec) return;
    spec.relatedMechanismIds = [ids[(index + ids.length - 1) % ids.length], ids[(index + 1) % ids.length]];
  });
}

export const LIFECYCLE_PATH: MechanismId[] = [
  "ingestion.async-buffer",
  "mergetree.part-anatomy",
  "mergetree.sorted-merge",
  "read.sparse-index",
  "read.granules",
  "read.column-pruning",
  "read.parallel-pipeline",
  "precompute.materialized-view",
  "retention.ttl-delete",
];

export const ARCHITECTURE_FAILURE_PATH: MechanismId[] = [
  "architecture.sharding",
  "architecture.replication",
  "architecture.keeper",
  "architecture.failure",
  "architecture.recovery",
];

export function mechanismById(id: string | null | undefined) {
  return MECHANISMS.find((entry) => entry.id === id);
}

export function districtById(id: string | null | undefined) {
  return DISTRICTS.find((entry) => entry.id === id);
}

export function searchMechanisms(query: string) {
  const needle = query.trim().toLowerCase();
  if (!needle) return MECHANISMS;
  return MECHANISMS.filter((entry) => [entry.title, entry.shortTitle, entry.tagline, entry.explanation, entry.misconception, entry.districtId].join(" ").toLowerCase().includes(needle));
}
